import base64
import subprocess
import zlib
from pathlib import Path

PATCH = ''
subprocess.run(['git', 'apply', '-'], input=zlib.decompress(base64.b64decode(PATCH)), check=True)
files = subprocess.check_output(['git', 'diff', '--name-only', '--', 'packages'], text=True)
Path('/tmp/pr10467-files.txt').write_text(files)
